#!/usr/bin/env python3
import subprocess, base64, os, sys
os.chdir(os.path.expanduser("~/IVANNA-OMEGA-SUPREME"))
r = subprocess.run(["git","pull","--rebase","origin","main"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0: print("ERROR pull:", r.stderr); sys.exit(1)

data = base64.b64decode("")
os.makedirs("app/src/main/java/com/ivanna/omega/audio", exist_ok=True)
with open("app/src/main/java/com/ivanna/omega/audio/Iso226Calibrator.kt", "wb") as f: f.write(data)
print(f"Escrito: app/src/main/java/com/ivanna/omega/audio/Iso226Calibrator.kt ({len(data)} bytes)")

r = subprocess.run(["git","add","app/src/main/java/com/ivanna/omega/audio/Iso226Calibrator.kt"], capture_output=True, text=True)
if r.returncode != 0: print("ERROR add:", r.stderr); sys.exit(1)

r = subprocess.run(["git","status","--porcelain","app/src/main/java/com/ivanna/omega/audio/Iso226Calibrator.kt"], capture_output=True, text=True)
if not r.stdout.strip(): print("Sin cambios — ya commitado"); sys.exit(0)

r = subprocess.run(["git","commit","-m","feat(iso226): Iso226Calibrator.kt — ISO 226:2003 tabla completa + applyAll() 3 capas"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0: print("ERROR commit:", r.stderr); sys.exit(1)

r = subprocess.run(["git","push","origin","main"], capture_output=True, text=True)
print(r.stdout.strip(), r.stderr.strip())
if r.returncode != 0: print("ERROR push:", r.stderr); sys.exit(1)
print("OK: app/src/main/java/com/ivanna/omega/audio/Iso226Calibrator.kt")
